import json

# Corrected spawn directions from Demo 3:
# 1: DOWN-RIGHT (+1, +1)
# 6: DOWN-LEFT (+1, -1)
# So: 9 like 1 (DOWN-RIGHT), 2 like 6 (DOWN-LEFT)

grid = [[4] * 21 for _ in range(23)]
grid[14] = [4]*11 + [5, 8] + [4]*8
grid[15] = [4]*11 + [9, 2] + [4]*8
grid[16] = [4]*10 + [9, 4, 4, 2] + [4]*7

original_non4 = set()
for r in range(23):
    for c in range(21):
        if grid[r][c] != 4:
            original_non4.add((r, c))

# Spawn: 9 DOWN-RIGHT, 2 DOWN-LEFT
spawn_info = {
    9: (1, 1),   # DOWN-RIGHT
    2: (1, -1),  # DOWN-LEFT
    5: None,
    8: None
}

for r in range(23):
    for c in range(21):
        val = grid[r][c]
        if spawn_info.get(val):
            dr, dc = spawn_info[val]
            nr, nc = r + dr, c + dc
            while nr < 23 and 0 <= nc < 21:
                if (nr, nc) not in original_non4 and grid[nr][nc] == 4:
                    grid[nr][nc] = val
                nr += dr
                nc += dc

print(json.dumps({"action": "submit", "grid": grid}))

